from pathlib import Path
import re

path=Path('vision-sync.js')
text=path.read_text('utf-8')
text=text.replace("const CONTRACT='ANCHOR_FREE_STRUCTURAL_V5';","const CONTRACT='ANCHOR_FREE_STRUCTURAL_V6';")
text=text.replace("topologyScore:0,denseScore:0,contourScore:0,phaseScore:0,angle:0", "topologyScore:0,denseScore:0,contourScore:0,phaseScore:0,scaleScore:0,intensityScore:0,angle:0")
text=text.replace(" · contour ${state.contourScore.toFixed(3)} · phase ${state.phaseScore.toFixed(3)} · verify ${state.verifyScore.toFixed(3)}", " · structural ${state.scaleScore.toFixed(3)} · recall ${state.intensityScore.toFixed(3)} · verify ${state.verifyScore.toFixed(3)}")

scale_code=r'''function znccPairs(a,b){const n=Math.min(a.length,b.length);if(n<20)return-1;let sa=0,sb=0,saa=0,sbb=0,sab=0;for(let i=0;i<n;i++){const av=a[i],bv=b[i];sa+=av;sb+=bv;saa+=av*av;sbb+=bv*bv;sab+=av*bv}const cov=sab-sa*sb/n,va=saa-sa*sa/n,vb=sbb-sb*sb/n;return va>1e-8&&vb>1e-8?cov/Math.sqrt(va*vb):-1}
function warpPoint(mx,my,c,s,radius,cx,cy,x,y){const nx=(x-mx)/(ROI_N/2),ny=(y-my)/(ROI_N/2);return{x:cx+(nx*c-ny*s)*radius,y:cy+(nx*s+ny*c)*radius}}
function warpIntensityNccFast(source,field,cx,cy,radius,angle,step=5){if(!source?.gray||!field?.gray||radius<=0)return{score:-1,ncc:-1,count:0};const mx=(source.w-1)/2,my=(source.h-1)/2,a=rad(angle),c=Math.cos(a),s=Math.sin(a),sv=[],rv=[];for(let y=7;y<source.h-7;y+=step)for(let x=7;x<source.w-7;x+=step){const nx=(x-mx)/(source.w/2),ny=(y-my)/(source.h/2),ring=Math.hypot(nx,ny);if(ring<.20||ring>.78)continue;const p=warpPoint(mx,my,c,s,radius,cx,cy,x,y);if(p.x<2||p.y<2||p.x>=field.w-2||p.y>=field.h-2)continue;sv.push(source.gray[Math.round(y)*source.w+Math.round(x)]);rv.push(bilinear(field.gray,field.w,field.h,p.x,p.y))}const ncc=znccPairs(sv,rv);return{score:ncc<-.99?-1:clamp((ncc+.15)/1.15,0,1),ncc,count:sv.length}}
function scaleAwareStructuralScore(source,field,cx,cy,radius,angle,step=3){if(!source?.gray||!field?.gray||radius<=0)return{score:-1,gradient:-1,topology:-1,edgeF1:0,negative:0,count:0};const mx=(source.w-1)/2,my=(source.h-1)/2,a=rad(angle),c=Math.cos(a),s=Math.sin(a),sgx=[],sgy=[],rgx=[],rgy=[],sh=[],rh=[],smags=[],rmags=[],signAgree=[];const off=2,wide=5;for(let y=8;y<source.h-8;y+=step)for(let x=8;x<source.w-8;x+=step){const nx=(x-mx)/(source.w/2),ny=(y-my)/(source.h/2),ring=Math.hypot(nx,ny);if(ring<.20||ring>.78)continue;const p=warpPoint(mx,my,c,s,radius,cx,cy,x,y),pxp=warpPoint(mx,my,c,s,radius,cx,cy,x+off,y),pxm=warpPoint(mx,my,c,s,radius,cx,cy,x-off,y),pyp=warpPoint(mx,my,c,s,radius,cx,cy,x,y+off),pym=warpPoint(mx,my,c,s,radius,cx,cy,x,y-off),wxp=warpPoint(mx,my,c,s,radius,cx,cy,x+wide,y),wxm=warpPoint(mx,my,c,s,radius,cx,cy,x-wide,y),wyp=warpPoint(mx,my,c,s,radius,cx,cy,x,y+wide),wym=warpPoint(mx,my,c,s,radius,cx,cy,x,y-wide);if([p,pxp,pxm,pyp,pym,wxp,wxm,wyp,wym].some(q=>q.x<1||q.y<1||q.x>=field.w-1||q.y>=field.h-1))continue;const si=y*source.w+x,sx1=source.gray[y*source.w+x+off],sx0=source.gray[y*source.w+x-off],sy1=source.gray[(y+off)*source.w+x],sy0=source.gray[(y-off)*source.w+x],sc=source.gray[si],swide=(source.gray[y*source.w+x+wide]+source.gray[y*source.w+x-wide]+source.gray[(y+wide)*source.w+x]+source.gray[(y-wide)*source.w+x])*.25,rvx1=bilinear(field.gray,field.w,field.h,pxp.x,pxp.y),rvx0=bilinear(field.gray,field.w,field.h,pxm.x,pxm.y),rvy1=bilinear(field.gray,field.w,field.h,pyp.x,pyp.y),rvy0=bilinear(field.gray,field.w,field.h,pym.x,pym.y),rc=bilinear(field.gray,field.w,field.h,p.x,p.y),rwide=(bilinear(field.gray,field.w,field.h,wxp.x,wxp.y)+bilinear(field.gray,field.w,field.h,wxm.x,wxm.y)+bilinear(field.gray,field.w,field.h,wyp.x,wyp.y)+bilinear(field.gray,field.w,field.h,wym.x,wym.y))*.25,gx=sx1-sx0,gy=sy1-sy0,grx=rvx1-rvx0,gry=rvy1-rvy0,hp=sc-swide,hr=rc-rwide;sgx.push(gx);sgy.push(gy);rgx.push(grx);rgy.push(gry);sh.push(hp);rh.push(hr);smags.push(Math.hypot(gx,gy));rmags.push(Math.hypot(grx,gry));signAgree.push(hp===0||hr===0?0.5:(hp>0)===(hr>0)?1:0)}if(sh.length<70)return{score:-1,gradient:-1,topology:-1,edgeF1:0,negative:0,count:sh.length};const gxN=znccPairs(sgx,rgx),gyN=znccPairs(sgy,rgy),highN=znccPairs(sh,rh),magN=znccPairs(smags,rmags),gradient=clamp(((gxN+gyN)*.5+1)/2,0,1),topology=clamp((highN+1)/2,0,1),magnitude=clamp((magN+1)/2,0,1),st=percentile(smags,.70),rt=percentile(rmags,.70);let tp=0,sp=0,rp=0,neg=0;for(let i=0;i<smags.length;i++){const se=smags[i]>=st,re=rmags[i]>=rt;if(se)sp++;if(re)rp++;if(se&&re)tp++;if(!se&&!re)neg++}const precision=rp?tp/rp:0,recall=sp?tp/sp:0,edgeF1=precision+recall?2*precision*recall/(precision+recall):0,negative=neg/smags.length,sign=signAgree.reduce((a,b)=>a+b,0)/signAgree.length,score=.30*gradient+.30*topology+.12*magnitude+.16*edgeF1+.07*negative+.05*sign;return{score,gradient,topology,magnitude,edgeF1,negative,sign,count:sh.length,gxN,gyN,highN,magN}}
'''
if 'function scaleAwareStructuralScore(' not in text:
    text=text.replace('function structuralPhaseScoreFast(',scale_code+'function structuralPhaseScoreFast(',1)

coarse=r'''async function coarseMatch(info,cfg){const atlas=await coarseAtlas(cfg),field=atlas.field,stride=cfg.width===32768?7:4,radii=cfg.width===32768?[6,9,13,18,25,34]:[5,8,12,17,24],angles=[0,45,90,135,180,225,270,315],topByRadius=new Map(radii.map(r=>[r,[]]));let bestSeen=0,rows=0;for(let y=stride;y<field.h-stride;y+=stride){for(let x=stride;x<field.w-stride;x+=stride){const target=pixelToGlobal(x*atlas.factor,y*atlas.factor,COARSE_Z,cfg);if(!inGlobalBounds(target))continue;for(const radius of radii)for(const angle of angles){const recall=warpIntensityNccFast(info.field,field,x,y,radius,angle,6);if(recall.score<0)continue;pushTop(topByRadius.get(radius),{x,y,radius,angle,score:recall.score,intensityScore:recall.score,intensityNcc:recall.ncc},120);bestSeen=Math.max(bestSeen,recall.score)}}rows++;if(rows%5===0){state.coarseScore=bestSeen;setDiag('SEARCH',`global normalized recall ${Math.round(y/field.h*100)}%`,'coarse-global');await sleep(0)}}const seeds=[];for(const radius of radii){const pool=topByRadius.get(radius)||[];for(const item of pool.slice(0,90)){const structural=scaleAwareStructuralScore(info.field,field,item.x,item.y,item.radius,item.angle,4),recall=warpIntensityNccFast(info.field,field,item.x,item.y,item.radius,item.angle,4);item.scaleScore=structural.score;item.intensityScore=recall.score;item.rankScore=.18*Math.max(0,recall.score)+.82*Math.max(0,structural.score)}pool.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));const chosen=[];for(const item of pool){if(chosen.every(seed=>Math.hypot(item.x-seed.x,item.y-seed.y)>=Math.max(11,radius*.50))){chosen.push(item);seeds.push(item);if(chosen.length>=8)break}}}seeds.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));if(!seeds.length)return null;const hypotheses=[];for(const seed of seeds.slice(0,36)){const recallTop=[];for(let y=seed.y-stride*1.6;y<=seed.y+stride*1.6;y+=2)for(let x=seed.x-stride*1.6;x<=seed.x+stride*1.6;x+=2){const target=pixelToGlobal(x*atlas.factor,y*atlas.factor,COARSE_Z,cfg);if(!inGlobalBounds(target))continue;for(const rf of [.86,.92,.97,1,1.03,1.08,1.14])for(const da of [-18,-12,-6,0,6,12,18]){const radius=seed.radius*rf,angle=angleNorm(seed.angle+da),recall=warpIntensityNccFast(info.field,field,x,y,radius,angle,5);pushTop(recallTop,{x,y,radius,angle,score:recall.score,intensityScore:recall.score},56)}}for(const item of recallTop.slice(0,42)){const structural=scaleAwareStructuralScore(info.field,field,item.x,item.y,item.radius,item.angle,3),recall=warpIntensityNccFast(info.field,field,item.x,item.y,item.radius,item.angle,3);item.scaleScore=structural.score;item.intensityScore=recall.score;item.rankScore=.12*Math.max(0,recall.score)+.88*Math.max(0,structural.score)}recallTop.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));hypotheses.push(recallTop[0]||seed);await sleep(0)}hypotheses.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));const best=hypotheses[0],second=hypotheses.find(x=>x!==best&&Math.hypot(x.x-best.x,x.y-best.y)>=Math.max(12,best.radius*.48)),margin=second?(best.rankScore??best.scaleScore)-(second.rankScore??second.scaleScore):(best.rankScore??best.scaleScore);return{...best,score:best.scaleScore??0,margin,atlas,hypotheses}}'''
text,n=re.subn(r'^async function coarseMatch\(info,cfg\)\{.*$',coarse,text,count=1,flags=re.M)
assert n==1,'coarseMatch replacement failed'

fine=r'''async function fineMatch(samples,cfg,pred,search=170,step=10,srcField=null){const atlasFactor=pred.atlas?.factor??(cfg.width===32768?4:2),scale=atlasFactor*(2**(FINE_Z-COARSE_Z)),centerX=pred.x*scale,centerY=pred.y*scale,radius=pred.radius*scale,fine=await fineFieldAround(cfg,centerX,centerY,radius,search),top=[];for(let y=fine.centerLocalY-search;y<=fine.centerLocalY+search;y+=step){for(let x=fine.centerLocalX-search;x<=fine.centerLocalX+search;x+=step)for(const rf of [.86,.92,.97,1,1.03,1.08,1.14])for(const da of [-15,-10,-5,0,5,10,15]){const rr=radius*rf,aa=angleNorm(pred.angle+da),recall=srcField?warpIntensityNccFast(srcField,fine.field,x,y,rr,aa,5):{score:0};pushTop(top,{x,y,radius:rr,angle:aa,score:recall.score,intensityScore:recall.score},120)}await sleep(0)}if(!top.length)return null;for(const item of top.slice(0,70)){const structural=srcField?scaleAwareStructuralScore(srcField,fine.field,item.x,item.y,item.radius,item.angle,3):{score:-1},recall=srcField?warpIntensityNccFast(srcField,fine.field,item.x,item.y,item.radius,item.angle,3):{score:0};item.scaleScore=structural.score;item.intensityScore=recall.score;item.rankScore=.10*Math.max(0,recall.score)+.90*Math.max(0,structural.score)}top.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));let best=top[0],ref=[];for(let y=best.y-18;y<=best.y+18;y+=2)for(let x=best.x-18;x<=best.x+18;x+=2)for(const rf of [.95,.98,1,1.02,1.05])for(const da of [-5,-2.5,0,2.5,5]){const rr=best.radius*rf,aa=angleNorm(best.angle+da),recall=srcField?warpIntensityNccFast(srcField,fine.field,x,y,rr,aa,4):{score:0};pushTop(ref,{x,y,radius:rr,angle:aa,score:recall.score,intensityScore:recall.score},80)}for(const item of ref.slice(0,64)){const structural=srcField?scaleAwareStructuralScore(srcField,fine.field,item.x,item.y,item.radius,item.angle,2):{score:-1},recall=srcField?warpIntensityNccFast(srcField,fine.field,item.x,item.y,item.radius,item.angle,2):{score:0};item.scaleScore=structural.score;item.intensityScore=recall.score;item.rankScore=.08*Math.max(0,recall.score)+.92*Math.max(0,structural.score)}ref.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));if(ref.length)best=ref[0];const all=(ref.length?ref:top),second=all.find(x=>x!==best&&Math.hypot(x.x-best.x,x.y-best.y)>=Math.max(22,best.radius*.10)),margin=second?(best.rankScore??best.scaleScore)-(second.rankScore??second.scaleScore):(best.rankScore??best.scaleScore),globalX=best.x+fine.minX*256,globalY=best.y+fine.minY*256;return{...best,score:best.scaleScore??best.score,globalX,globalY,margin,fieldGrid:fine,scaleFromCoarse:scale}}'''
text,n=re.subn(r'^async function fineMatch\(samples,cfg,pred,search=170,step=10,srcField=null\)\{.*$',fine,text,count=1,flags=re.M)
assert n==1,'fineMatch replacement failed'

global_match=r'''async function globalMatch(info,cfg){const coarseSearch=await coarseMatch(info,cfg);if(!coarseSearch)return{coarse:null,fine:null};state.coarseScore=coarseSearch.score;state.coarseMargin=coarseSearch.margin||0;setDiag('SEARCH','scale-aware structural candidates found; refining tiles','fine-global');const finals=[];for(const hypothesis of (coarseSearch.hypotheses||[coarseSearch]).slice(0,COARSE_BEAM)){const fine=await fineMatch(info.samples,cfg,{...hypothesis,atlas:coarseSearch.atlas},230,12,info.field);if(fine){const structural=scaleAwareStructuralScore(info.field,fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle,2),recall=warpIntensityNccFast(info.field,fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle,2),verify=verifyAt(fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle,info.verifySamples),combined=.92*Math.max(0,structural.score)+.08*Math.max(0,recall.score);finals.push({fine:{...fine,scaleScore:structural.score,intensityScore:recall.score,structuralDetail:structural},hypothesis,verify,combined})}await sleep(0)}if(!finals.length)return{coarse:coarseSearch,fine:null};finals.sort((a,b)=>b.combined-a.combined);const winner=finals[0],second=finals.find(item=>Math.hypot(item.fine.globalX-winner.fine.globalX,item.fine.globalY-winner.fine.globalY)>=Math.max(70,winner.fine.radius*.25)),beamMargin=second?winner.combined-second.combined:winner.combined,fine={...winner.fine,localMargin:winner.fine.margin,beamMargin,verifyScore:winner.verify.score,topologyScore:winner.verify.topology,combinedScore:winner.combined,margin:Math.min(winner.fine.margin,beamMargin)},coarse={...winner.hypothesis,score:winner.hypothesis.scaleScore??coarseSearch.score,margin:coarseSearch.margin,atlas:coarseSearch.atlas,beamResolved:true};return{coarse,fine,alternatives:finals.map(item=>({x:item.fine.globalX,y:item.fine.globalY,angle:item.fine.angle,scaleScore:item.fine.scaleScore,intensityScore:item.fine.intensityScore,combinedScore:item.combined}))}}'''
text,n=re.subn(r'^async function globalMatch\(info,cfg\)\{.*$',global_match,text,count=1,flags=re.M)
assert n==1,'globalMatch replacement failed'

gate=r'''function matchGate(coarse,fine,info,cfg){if(!cfg.geometryOk)return`geometry-residual p95=${cfg.p95.toFixed(6)}`;if(info.positiveCount<24)return`insufficient-structural-features ${info.positiveCount}`;if(info.contrast<.10)return`low-normalized-contrast ${info.contrast.toFixed(3)}`;if(!coarse)return'no-coarse-match';if(coarse.score<.50)return`coarse-scale-structure ${coarse.score.toFixed(3)}`;if(!fine)return'no-fine-match';if(fine.scaleScore<.58)return`scale-aware-structure ${fine.scaleScore.toFixed(3)}`;if(fine.intensityScore<.42)return`candidate-recall ${fine.intensityScore.toFixed(3)}`;if(Number.isFinite(fine.beamMargin)&&fine.beamMargin<.010)return`global-ambiguous ${fine.beamMargin.toFixed(3)}`;return''}'''
text,n=re.subn(r'^function matchGate\(coarse,fine,info,cfg\)\{.*$',gate,text,count=1,flags=re.M)
assert n==1,'matchGate replacement failed'

register=r'''async function registerFrame(cfg,mapId){const roiCanvas=VISION.captureRoi(192);if(!roiCanvas)return{reason:'capture-frame-unavailable'};const info=roiSamples(roiCanvas);let coarse=null,fine=null;if(state.mode==='local'&&state.last){fine=await localFineMatch(info,cfg,state.last,160);if(fine){const verify=verifyAt(fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle,info.verifySamples);fine={...fine,verifyScore:verify.score,topologyScore:verify.topology,beamMargin:fine.margin};coarse={score:state.coarseScore,margin:state.coarseMargin,beamResolved:true}}}else if(state.mode==='confirm'&&state.pending?.match){fine=await localFineMatch(info,cfg,state.pending.match,140);if(fine){const verify=verifyAt(fine.fieldGrid.field,fine.x,fine.y,fine.radius,fine.angle,info.verifySamples);fine={...fine,verifyScore:verify.score,topologyScore:verify.topology,beamMargin:fine.margin};coarse={score:state.pending.coarseScore,margin:state.pending.coarseMargin,beamResolved:true}}}else{state.globalSearches++;const global=await globalMatch(info,cfg);coarse=global.coarse;fine=global.fine}if(coarse){state.coarseScore=coarse.score;state.coarseMargin=coarse.margin||0}if(fine){state.fineScore=fine.score;state.fineMargin=fine.margin||0;state.verifyScore=fine.verifyScore||0;state.topologyScore=fine.topologyScore||0;state.scaleScore=fine.scaleScore||0;state.intensityScore=fine.intensityScore||0;state.angle=fine.angle;state.radius=fine.radius}const reason=matchGate(coarse,fine,info,cfg);if(reason)return{reason,coarse,fine,info};const target=pixelToGlobal(fine.globalX,fine.globalY,FINE_Z,cfg);if(!target||!inGlobalBounds(target))return{reason:'target-out-of-global-bounds',coarse,fine,info};return{reason:'',coarse,fine,info,target,mapId}}'''
text,n=re.subn(r'^async function registerFrame\(cfg,mapId\)\{.*$',register,text,count=1,flags=re.M)
assert n==1,'registerFrame replacement failed'

selftest=r'''async function selfTest(profile='gfn'){const cfg=MAPS[1],synth=await syntheticRoi(profile),info=roiSamples(synth.canvas),match=await globalMatch(info,cfg),fine=match.fine,coarse=match.coarse,scale=fine?.scaleFromCoarse||1,actual=fine?{x:fine.globalX/scale,y:fine.globalY/scale,radius:fine.radius/scale,angle:fine.angle}:null,error=actual?Math.hypot(actual.x-synth.expected.x,actual.y-synth.expected.y):Infinity,rotationError=actual?Math.min(angleDiff(actual.angle,synth.angle),angleDiff(angleNorm(actual.angle+180),synth.angle)):Infinity,gateReason=matchGate(coarse,fine,info,cfg),atlas=coarse?.atlas||await coarseAtlas(cfg),truthStructural=scaleAwareStructuralScore(info.field,atlas.field,synth.expected.x,synth.expected.y,synth.radius,synth.angle,2),truthRecall=warpIntensityNccFast(info.field,atlas.field,synth.expected.x,synth.expected.y,synth.radius,synth.angle,2);return{ok:!!actual&&error<=10&&rotationError<=28&&!gateReason,profile,gateReason,error,rotationError,score:fine?.score??-1,scaleScore:fine?.scaleScore??-1,intensityScore:fine?.intensityScore??-1,verifyScore:fine?.verifyScore??-1,margin:fine?.margin??0,coarseScore:coarse?.score??-1,coarseMargin:coarse?.margin??0,truth:{scaleScore:truthStructural.score,gradient:truthStructural.gradient,topology:truthStructural.topology,edgeF1:truthStructural.edgeF1,negative:truthStructural.negative,intensityScore:truthRecall.score,intensityNcc:truthRecall.ncc,radius:synth.radius,angle:synth.angle},expected:synth.expected,actual,features:info.samples.length,positiveFeatures:info.positiveCount,negativeFeatures:info.negativeCount,contrast:info.contrast}}'''
text,n=re.subn(r"^async function selfTest\(profile='gfn'\)\{.*$",selftest,text,count=1,flags=re.M)
assert n==1,'selfTest replacement failed'

text=text.replace("state.verifyScore=0;state.denseScore=0;state.contourScore=0;state.phaseScore=0;state.firstSearchAt=0", "state.verifyScore=0;state.denseScore=0;state.contourScore=0;state.phaseScore=0;state.scaleScore=0;state.intensityScore=0;state.firstSearchAt=0")
text=text.replace("verifyScore:state.verifyScore,denseScore:state.denseScore,contourScore:state.contourScore,phaseScore:state.phaseScore,topologyScore:state.topologyScore", "verifyScore:state.verifyScore,scaleScore:state.scaleScore,intensityScore:state.intensityScore,topologyScore:state.topologyScore")
path.write_text(text,'utf-8')
